-- MySQL-Erweiterung für die AJAX-Suche. In der bestehenden Datenbank ausführen.
CREATE TABLE IF NOT EXISTS wiki_pages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,category VARCHAR(150) NOT NULL DEFAULT '',url VARCHAR(500) NOT NULL,content TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_title(title),INDEX idx_category(category)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
